   in_conf && /^INSTALL_RAY=/            { print "INSTALL_RAY=\"" ray_inst  "\"" ; next }
   in_conf && /^NS_RAY=/                 { print "NS_RAY=\"" ray_ns "\"" ; next }
   in_conf && /^RAY_VERSION=/            { print "RAY_VERSION=\"" ray_ver  "\"" ; next }
   in_conf && /^RAY_OPERATOR_VERSION=/   { print "RAY_OPERATOR_VERSION=\"" ray_opver "\"" ; next }
   in_conf && /^RAY_HEAD_CPU=/           { print "RAY_HEAD_CPU=\"" ray_hcpu "\"" ; next }
   in_conf && /^RAY_HEAD_MEM=/           { print "RAY_HEAD_MEM=\"" ray_hmem "\"" ; next }
   in_conf && /^RAY_WORKER_REPLICAS=/    { print "RAY_WORKER_REPLICAS=\"" ray_wreps "\"" ; next }
   in_conf && /^RAY_WORKER_CPU=/         { print "RAY_WORKER_CPU=\"" ray_wcpu "\"" ; next }
   in_conf && /^RAY_WORKER_MEM=/         { print "RAY_WORKER_MEM=\"" ray_wmem "\"" ; next }
   in_conf && /^RAY_WORKER_GPU=/         { print "RAY_WORKER_GPU=\"" ray_wgpu "\"" ; next }
